diff --git a/repro/check.js b/repro/check.js
new file mode 100644
index 000000000..4f8b25efc
--- /dev/null
+++ b/repro/check.js
@@ -0,0 +1,28 @@
+// Reproduction check for "Type assertion regression in TypeScript 5.7".
+// Exit code is non-zero while the bug is present, zero once fixed.
+// Run from the repo root:  node repro/check.js [path/to/typescript.js] [file.ts]
+// The code under test is repro/report.ts, the code from the report verbatim.
+const path = require("path");
+const ts = require(path.resolve(process.argv[2] || "built/local/typescript.js"));
+const file = path.resolve(process.argv[3] || path.join(__dirname, "report.ts"));
+
+const program = ts.createProgram([file], {
+    strict: true, noEmit: true, target: ts.ScriptTarget.ES2022, lib: ["lib.es2022.d.ts"], types: [],
+});
+const checker = program.getTypeChecker();
+const sf = program.getSourceFile(file);
+let decl;
+(function visit(n) {
+    if (ts.isTypeAliasDeclaration(n) && n.name.text === "Test") decl = n;
+    ts.forEachChild(n, visit);
+})(sf);
+
+const actual = checker.typeToString(checker.getTypeAtLocation(decl.name), undefined, ts.TypeFormatFlags.NoTruncation);
+const expected = '{ prop1: "hello"; }';
+console.log(`TypeScript ${ts.version}`);
+console.log(`type Test = ${actual}`);
+if (actual !== expected) {
+    console.error(`FAIL: expected type Test = ${expected}`);
+    process.exit(1);
+}
+console.log("OK");
diff --git a/repro/report.ts b/repro/report.ts
new file mode 100644
index 000000000..199956eab
--- /dev/null
+++ b/repro/report.ts
@@ -0,0 +1,22 @@
+type Wrapper<T> = {
+    _type: T
+}
+
+function stringWrapper(): Wrapper<string> {
+    return { _type: "" }
+}
+
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj }
+}
+
+const value = objWrapper({
+    prop1: stringWrapper() as Wrapper<"hello">
+})
+
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>> 
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> } 
+    : T['_type']
+
+type Test = Unwrap<typeof value>
+
